import pandas as pd
import numpy as np

# Load the GHG data
ghg_data = pd.read_csv('chunks_csv/getisord/getisord_2023_ghg.csv')
# Load the adjacency data
adjacency_data = pd.read_csv(ADJACENCY_PATH)

# Merge GHG data with adjacency data
merged_data = adjacency_data.merge(ghg_data, on='borough', how='left')

# Create a function to calculate the combined GHG value for each borough and its neighbors
def calculate_combined_ghg(borough):
    neighbors = merged_data[merged_data['borough'] == borough]['neighbor'].values
    combined_ghg = merged_data[merged_data['borough'].isin([borough] + list(neighbors))]['GHG_value']
    return combined_ghg.sum()

# Calculate the combined GHG values for all boroughs
combined_ghg_values = merged_data['borough'].unique()
combined_ghg_dict = {borough: calculate_combined_ghg(borough) for borough in combined_ghg_values}

# Calculate the citywide average GHG value
citywide_average = ghg_data['GHG_value'].mean()

# Calculate z-scores for each borough's combined GHG value
z_scores = {}
for borough, combined_ghg in combined_ghg_dict.items():
    if not np.isnan(combined_ghg):
        z_score = (combined_ghg - citywide_average) / (ghg_data['GHG_value'].std() / np.sqrt(len(ghg_data)))
        z_scores[borough] = z_score

# Identify hot and cold spots based on z-scores
hot_spots = {borough: z for borough, z in z_scores.items() if z > 1.96}
cold_spots = {borough: z for borough, z in z_scores.items() if z < -1.96}

# Prepare the final output
final_results = []
for borough, z in hot_spots.items():
    final_results.append(f"{borough} (HOT, z-score = {z})")
for borough, z in cold_spots.items():
    final_results.append(f"{borough} (COLD, z-score = {z})")

# Print the final answer
if final_results:
    print(", ".join(final_results))
else:
    print("FINAL ANSWER: none")
